"""Render the tap formula from a stable Lector release's verified checksums."""

import argparse
from pathlib import Path
import re


VERSION = r"(?:0|[1-9][0-9]*)(?:\.(?:0|[1-9][0-9]*)){2}"
TARGETS = {
    "macos": {"arm": "aarch64-apple-darwin", "intel": "x86_64-apple-darwin"},
    "linux": {"arm": "aarch64-unknown-linux-musl", "intel": "x86_64-unknown-linux-musl"},
}


def render_formula(version, checksums):
    if not re.fullmatch(VERSION, version):
        raise ValueError(f"Expected a stable Lector version, got {version!r}")

    names = {f"lector-{target}.tar.gz" for targets in TARGETS.values() for target in targets.values()}
    digests = {}
    for line in checksums.splitlines():
        digest, name = line.split()
        if name in names:
            if name in digests or not re.fullmatch(r"[0-9a-f]{64}", digest):
                raise ValueError(f"Invalid or duplicate checksum for {name}")
            digests[name] = digest
    if missing := names - digests.keys():
        raise ValueError(f"Missing checksums for {', '.join(sorted(missing))}")

    source_blocks = []
    for os, targets in TARGETS.items():
        branches = []
        for arch, target in targets.items():
            name = f"lector-{target}.tar.gz"
            url = f"https://github.com/n0ot/lector/releases/download/v{version}/{name}"
            branches.append(
                f'    on_{arch} do\n'
                f'      url "{url}"\n'
                f'      sha256 "{digests[name]}"\n'
                f'    end'
            )
        source_blocks.append(f"  on_{os} do\n" + "\n\n".join(branches) + "\n  end")
    sources = "\n\n".join(source_blocks)

    return f'''# Generated by .github/scripts/publish_homebrew.py in n0ot/lector.
class Lector < Formula
  desc "Screen reader for Unix-like terminals"
  homepage "https://github.com/n0ot/lector"
  version "{version}"
  license "MIT"

{sources}

  head do
    url "https://github.com/n0ot/lector.git", branch: "master"

    depends_on "rustup" => :build
  end

  def install
    if build.head?
      toolchain = Utils.safe_popen_read("scripts/check-rust-toolchain", "--channel").strip
      system "rustup", "toolchain", "install", toolchain, "--profile", "minimal"
      system "rustup", "run", toolchain, "cargo", "install", *std_cargo_args, "--bin", "lector"
    else
      bin.install "lector"
    end
  end

  test do
    expected = build.head? ? "lector " : "lector #{{version}}"
    assert_match expected, shell_output("#{{bin}}/lector --version")
  end
end
'''


def update_formula(path, version, checksums):
    updated = render_formula(version, checksums)
    if path.exists():
        current = path.read_text(encoding="utf-8")
        match = re.search(rf'^  version "({VERSION})"$', current, re.MULTILINE)
        if not match:
            raise ValueError(f"Cannot determine existing version in {path}")
        if tuple(map(int, match[1].split("."))) > tuple(map(int, version.split("."))):
            return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(updated, encoding="utf-8")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("version")
    parser.add_argument("checksums", type=Path)
    parser.add_argument("formula", type=Path)
    args = parser.parse_args()
    try:
        update_formula(args.formula, args.version, args.checksums.read_text(encoding="utf-8"))
    except ValueError as error:
        parser.exit(1, f"{error}\n")


if __name__ == "__main__":
    main()
